19	// jsdom workarounds for the unit-test environment. Real browsers (and the
20	// playwright e2e suite) do not need any of these patches, so we gate on the
21	// jsdom-specific user-agent string and only patch when running there.
22	//
23	// 1. jsdom >= 24.1.1 collapses an existing text-node DOM selection to the
24	//    start of the focused element when HTMLElement.focus() is called on a
25	//    contenteditable ancestor. Real browsers (and happy-dom) preserve the
26	//    selection. Restore the pre-focus selection when this happens.
27	// 2. jsdom does not implement Range.prototype.getBoundingClientRect, so
28	//    Lexical's scroll-into-view path throws when reading it. Stub it.
29	const isJsdom =
30	  typeof navigator !== 'undefined' && /\bjsdom\//.test(navigator.userAgent);
31	if (isJsdom) {
32	  const originalFocus = HTMLElement.prototype.focus;
33	  function focusPreservingSelection(
34	    this: HTMLElement,
35	    options?: FocusOptions,
36	  ): void {
37	    const sel = document.getSelection();
38	    const snapshot =
39	      sel && sel.rangeCount > 0
40	        ? {
41	            anchorNode: sel.anchorNode,
42	            anchorOffset: sel.anchorOffset,
43	            focusNode: sel.focusNode,
44	            focusOffset: sel.focusOffset,
45	          }
46	        : null;
47	    originalFocus.call(this, options);
48	    if (
49	      snapshot !== null &&
50	      snapshot.anchorNode !== null &&
51	      snapshot.focusNode !== null &&
52	      this.contains(snapshot.anchorNode) &&
53	      this.contains(snapshot.focusNode) &&
54	      sel !== null &&
55	      (sel.anchorNode !== snapshot.anchorNode ||
56	        sel.anchorOffset !== snapshot.anchorOffset ||
57	        sel.focusNode !== snapshot.focusNode ||
58	        sel.focusOffset !== snapshot.focusOffset)
59	    ) {
60	      try {
61	        sel.setBaseAndExtent(
62	          snapshot.anchorNode,
63	          snapshot.anchorOffset,
64	          snapshot.focusNode,
65	          snapshot.focusOffset,
66	        );
67	      } catch {
68	        // Ignore restoration failures; tests that depend on selection will
69	        // surface them downstream.
70	      }
71	    }
72	  }
73	  HTMLElement.prototype.focus = focusPreservingSelection;
74	
75	  // jsdom's HTMLElement.contentEditable is a plain property that doesn't
76	  // synchronize with the 'contenteditable' DOM attribute. Real browsers
77	  // (and the spec) require them to stay in sync, so override the
78	  // property to delegate to getAttribute/setAttribute.
79	  const ceDescriptor = Object.getOwnPropertyDescriptor(
80	    HTMLElement.prototype,
81	    'contentEditable',
82	  );
83	  if (!ceDescriptor || ceDescriptor.configurable !== false) {
84	    Object.defineProperty(HTMLElement.prototype, 'contentEditable', {
85	      configurable: true,
86	      get(this: HTMLElement) {
87	        const attr = this.getAttribute('contenteditable');
88	        if (attr === 'true' || attr === '') {
89	          return 'true';
90	        }
91	        if (attr === 'false') {
92	          return 'false';
93	        }
94	        return 'inherit';
95	      },
96	      set(this: HTMLElement, value: string) {
97	        if (value === 'inherit') {
98	          this.removeAttribute('contenteditable');
99	        } else {
100	          this.setAttribute('contenteditable', value);
101	        }
102	      },
103	    });
104	  }
105	
106	  if (typeof Range.prototype.getBoundingClientRect !== 'function') {
107	    // jsdom does not implement layout, so a zero-rect stub is sufficient
108	    // for code paths that only need a DOMRect-shaped value (like
109	    // Lexical's scroll-into-view computation).
110	    Range.prototype.getBoundingClientRect = function (): DOMRect {
111	      return {
112	        bottom: 0,
113	        height: 0,
114	        left: 0,
115	        right: 0,
116	        toJSON() {
117	          return this;
118	        },
119	        top: 0,
120	        width: 0,
121	        x: 0,
122	        y: 0,
123	      } as DOMRect;
124	    };
125	  }
126	
127	  // jsdom does not implement PointerEvent. Provide a minimal subclass of
128	  // Event carrying the fields our event handlers read (button, buttons,
129	  // clientX/Y, pointerType). Tests that need richer behavior can extend
130	  // or override per-event.
131	  if (
132	    typeof (globalThis as {PointerEvent?: unknown}).PointerEvent !== 'function'
133	  ) {
134	    interface PointerEventLikeInit extends EventInit {
135	      button?: number;
136	      buttons?: number;
137	      clientX?: number;
138	      clientY?: number;
139	      pointerType?: string;
140	    }
141	    class PointerEventPolyfill extends Event {
142	      button: number;
143	      buttons: number;
144	      clientX: number;
145	      clientY: number;
146	      pointerType: string;
147	      constructor(type: string, options: PointerEventLikeInit = {}) {
148	        super(type, options);
149	        this.button = options.button ?? 0;
150	        this.buttons = options.buttons ?? 0;
151	        this.clientX = options.clientX ?? 0;
152	        this.clientY = options.clientY ?? 0;
153	        this.pointerType = options.pointerType || 'mouse';
154	      }
155	    }
156	    (globalThis as {PointerEvent: unknown}).PointerEvent = PointerEventPolyfill;
157	  }
158	}
