31	export interface LinkConfig {
32	  /**
33	   * If this function is specified a {@link PASTE_COMMAND}
34	   * listener will be registered to wrap selected nodes
35	   * when a URL is pasted and `validateUrl(url)` returns true.
36	   * The default of `undefined` will not register this listener.
37	   *
38	   * In the implementation of {@link TOGGLE_LINK_COMMAND}
39	   * it will reject URLs that return false when specified.
40	   * The default of `undefined` will always accept URLs.
41	   */
42	  validateUrl: undefined | ((url: string) => boolean);
43	  /**
44	   * The default anchor tag attributes to use for
45	   * {@link TOGGLE_LINK_COMMAND}
46	   */
47	  attributes: undefined | LinkAttributes;
48	}
49	
50	const defaultProps: LinkConfig = {
51	  attributes: undefined,
52	  validateUrl: undefined,
53	};
54	
55	/** @internal */
56	export function registerLink(
57	  editor: LexicalEditor,
58	  stores: NamedSignalsOutput<LinkConfig>,
59	) {
60	  return mergeRegister(
61	    editor.registerNodeTransform(LinkNode, $linkNodeTransform),
62	    editor.registerCommand(
63	      TOGGLE_LINK_COMMAND,
64	      payload => {
65	        const validateUrl = stores.validateUrl.peek();
66	        const attributes = stores.attributes.peek();
67	        if (payload === null) {
68	          $toggleLink(null);
69	          return true;
70	        } else if (typeof payload === 'string') {
71	          if (validateUrl === undefined || validateUrl(payload)) {
72	            $toggleLink(payload, attributes);
73	            return true;
74	          }
75	          return false;
76	        } else {
77	          const {url, target, rel, title} = payload;
78	          $toggleLink(url, {
79	            ...attributes,
80	            rel,
81	            target,
82	            title,
83	          });
84	          return true;
85	        }
86	      },
87	      COMMAND_PRIORITY_EDITOR,
88	    ),
89	    effect(() => {
90	      const validateUrl = stores.validateUrl.value;
91	      if (!validateUrl) {
92	        return;
93	      }
94	      const attributes = stores.attributes.value;
95	      return editor.registerCommand(
96	        PASTE_COMMAND,
97	        event => {
98	          const selection = $getSelection();
99	          if (
100	            !$isRangeSelection(selection) ||
101	            selection.isCollapsed() ||
102	            !objectKlassEquals(event, ClipboardEvent)
103	          ) {
104	            return false;
105	          }
106	          if (event.clipboardData === null) {
107	            return false;
108	          }
109	          const clipboardText = event.clipboardData.getData('text');
110	          if (!validateUrl(clipboardText)) {
111	            return false;
112	          }
113	          // If we select nodes that are elements then avoid applying the link.
114	          if (!selection.getNodes().some(node => $isElementNode(node))) {
115	            editor.dispatchCommand(TOGGLE_LINK_COMMAND, {
116	              ...attributes,
117	              url: clipboardText,
118	            });
119	            event.preventDefault();
120	            return true;
121	          }
122	          return false;
123	        },
124	        COMMAND_PRIORITY_LOW,
125	      );
126	    }),
127	  );
128	}
