130	/**
131	 * Provides {@link LinkNode}, an implementation of
132	 * {@link TOGGLE_LINK_COMMAND}, and a {@link PASTE_COMMAND}
133	 * listener to wrap selected nodes in a link when a
134	 * URL is pasted and `validateUrl` is defined.
135	 */
136	export const LinkExtension = defineExtension({
137	  build(editor, config, state) {
138	    return namedSignals(config);
139	  },
140	  config: defaultProps,
141	  mergeConfig(config, overrides) {
142	    const merged = shallowMergeConfig(config, overrides);
143	    if (config.attributes) {
144	      merged.attributes = shallowMergeConfig(
145	        config.attributes,
146	        merged.attributes,
147	      );
148	    }
149	    return merged;
150	  },
151	  name: '@lexical/link/Link',
152	  nodes: () => [LinkNode],
153	  register(editor, config, state) {
154	    return registerLink(editor, state.getOutput());
155	  },
156	});
